
-- Table for membership entity, primary key is auto generated id by postgresql
CREATE TABLE memberships (
                             id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                             name VARCHAR(100) NOT NULL,
                             description TEXT
);

-- Table for perk entity, primary key is auto generated id by postgresql
CREATE TABLE perks (
                       id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                       title VARCHAR(150) NOT NULL,
                       description TEXT,
                       membership_id BIGINT NOT NULL,
                       expiry_date DATE,

                       CONSTRAINT fk_perks_membership
                           FOREIGN KEY (membership_id)
                               REFERENCES memberships(id)
                               ON DELETE CASCADE -- if a membership is deleted, so are any associated perks
);

-- Add index so PostgreSQL can find Perks easier from membership ids
CREATE INDEX idx_perks_membership_id
    ON perks(membership_id);